() => {
  const pick = (el) => { if (!el) return null; const s = getComputedStyle(el); return { tag: el.tagName, text: (el.innerText||'').slice(0,40), font: s.fontFamily, size: s.fontSize, weight: s.fontWeight, color: s.color, bg: s.backgroundColor, bgImg: s.backgroundImage.slice(0,120), radius: s.borderRadius, border: s.border, shadow: s.boxShadow.slice(0,100), padding: s.padding }; };
  const all = [...document.querySelectorAll('*')];
  const byText = (t) => all.filter(e => e.children.length === 0 && (e.innerText||'').trim().startsWith(t))[0];
  const btn = [...document.querySelectorAll('button')].find(b => /Verify and Select Time/.test(b.innerText));
  const login = [...document.querySelectorAll('button')].find(b => /Login/.test(b.innerText));
  const input = document.querySelector('input[placeholder*="Parent"]') || document.querySelector('input');
  const h = byText('Unlock');
  const card = btn && btn.closest('div[class]') ;
  let cardEl = btn; for (let i=0;i<8 && cardEl;i++){ cardEl = cardEl.parentElement; if (cardEl && getComputedStyle(cardEl).borderRadius !== '0px' && getComputedStyle(cardEl).backgroundColor !== 'rgba(0, 0, 0, 0)') break; }
  const bookHead = byText('Book a');
  const fonts = [...new Set(all.map(e => getComputedStyle(e).fontFamily))].slice(0,10);
  const links = [...document.querySelectorAll('link[href*="font"], style')].map(l => l.href || '').filter(Boolean).slice(0,5);
  return { body: pick(document.body), heading: pick(h), bookHead: pick(bookHead), btn: pick(btn), login: pick(login), input: pick(input), card: pick(cardEl), fonts, links };
}

