input.function:
() => {
  const leaves = [...document.querySelectorAll('*')].filter(e => e.children.length <= 3);
  const find = (re) => leaves.find(e => re.test((e.innerText||'').trim()));
  const s = (el) => el ? (({fontFamily, fontSize, fontWeight, color, backgroundColor, lineHeight}) => ({text:(el.innerText||'').slice(0,50), fontFamily, fontSize, fontWeight, color, backgroundColor, lineHeight}))(getComputedStyle(el)) : null;
  const pageBg = [...document.querySelectorAll('div')].map(d => getComputedStyle(d).backgroundColor).filter(c => c !== 'rgba(0, 0, 0, 0)');
  const counts = {}; pageBg.forEach(c => counts[c] = (counts[c]||0)+1);
  const prog = [...document.querySelectorAll('div')].filter(d => { const r = d.getBoundingClientRect(); return r.height > 0 && r.height <= 6 && r.width > 20 && r.width < 80; }).map(d => getComputedStyle(d).backgroundColor);
  const inputWrap = document.querySelector('input'); let w = inputWrap; for (let i=0;i<4;i++){ w = w.parentElement; const st = getComputedStyle(w); if (st.borderTopWidth !== '0px') break; }
  const fs = getComputedStyle(w);
  return { unlock: s(find(/^Unlock/)), bookFree: s(find(/^Book a/)), happy: s(find(/^30K\+/)), faq: s(find(/^Frequently/)), bgCounts: counts, progress: prog.slice(0,6), inputBorder: { border: fs.border, radius: fs.borderRadius } };
}

