node -v; docker --version 2>&1; docker compose version 2>&1; node -e '
const fmt=(loc,tz,iso,o)=>new Intl.DateTimeFormat(loc,{timeZone:tz,hour:"numeric",minute:"2-digit",...o}).format(new Date(iso));
const jan="2026-01-15T15:30:00Z", jul="2026-07-15T15:30:00Z";
for (const [loc,tz] of [["en-US","America/New_York"],["en-GB","America/New_York"],["en-US","America/Phoenix"],["en-US","Europe/London"],["en-GB","Europe/London"],["en-IE","Europe/Dublin"],["en-GB","Europe/Dublin"],["en-US","Asia/Kolkata"],["en-IN","Asia/Kolkata"],["en-GB","Asia/Kolkata"]])
  console.log(loc.padEnd(6),tz.padEnd(17),"jan:",fmt(loc,tz,jan,{timeZoneName:"short"}).padEnd(16),"jul:",fmt(loc,tz,jul,{timeZoneName:"short"}).padEnd(16),"| shortOffset:",fmt(loc,tz,jul,{timeZoneName:"shortOffset"}),"| longGeneric:",fmt(loc,tz,jul,{timeZoneName:"longGeneric"}));
console.log("detected:", Intl.DateTimeFormat().resolvedOptions().timeZone, "| Calcutta resolves as:", new Intl.DateTimeFormat("en",{timeZone:"Asia/Calcutta"}).resolvedOptions().timeZone);
console.log("Temporal:", typeof globalThis.Temporal, "| supportedValuesOf count:", Intl.supportedValuesOf("timeZone").length, "| has Asia/Kolkata:", Intl.supportedValuesOf("timeZone").includes("Asia/Kolkata"));
'

