input.command:
node -e '
const f=(iso,tz,loc="en-US")=>new Intl.DateTimeFormat(loc,{timeZone:tz,weekday:"short",day:"numeric",month:"short",hour:"numeric",minute:"2-digit",timeZoneName:"short"}).format(new Date(iso));
const zones=[["America/Los_Angeles","en-US"],["America/Phoenix","en-US"],["America/New_York","en-US"],["Europe/London","en-GB"],["Asia/Kolkata","en-IN"]];
console.log("== same mentor slot (20:30 IST = 15:00Z) across the autumn changes ==");
for (const d of ["2026-10-23","2026-10-27","2026-11-03"]) console.log(d, zones.map(([z,l])=>f(d+"T15:00:00Z",z,l)).join(" | "));
console.log("== US-evening slot (23:00Z) ==");
for (const d of ["2026-10-23","2026-10-27","2026-11-03"]) console.log(d, zones.map(([z,l])=>f(d+"T23:00:00Z",z,l)).join(" | "));
console.log("== London fall-back night, hourly UTC slots ==");
for (const t of ["2026-10-24T23:00:00Z","2026-10-25T00:00:00Z","2026-10-25T01:00:00Z","2026-10-25T02:00:00Z"]) console.log(t, f(t,"Europe/London","en-GB"), "|", f(t,"Asia/Kolkata","en-IN"));
console.log("== New York fall-back night ==");
for (const t of ["2026-11-01T04:00:00Z","2026-11-01T05:00:00Z","2026-11-01T06:00:00Z","2026-11-01T07:00:00Z"]) console.log(t, f(t,"America/New_York"));
console.log("== spring-forward nights (hour that does not exist) ==");
for (const t of ["2026-03-08T06:00:00Z","2026-03-08T07:00:00Z"]) console.log(t, f(t,"America/New_York"));
for (const t of ["2026-03-29T00:00:00Z","2026-03-29T01:00:00Z"]) console.log(t, f(t,"Europe/London","en-GB"));
console.log("== parent day vs mentor day ==");
console.log(f("2026-10-27T01:00:00Z","America/Los_Angeles"), "->", f("2026-10-27T01:00:00Z","Asia/Kolkata","en-IN"));
'

