1	<!DOCTYPE html>
2	<html>
3	<head>
4	  <meta charset="utf-8">
5	  <title>Superpowers Brainstorming</title>
6	  <style>
7	    /*
8	     * BRAINSTORM COMPANION FRAME TEMPLATE
9	     *
10	     * This template provides a consistent frame with:
11	     * - OS-aware light/dark theming
12	     * - Header branding and connection status
13	     * - Scrollable main content area
14	     * - CSS helpers for common UI patterns
15	     *
16	     * Content is injected via placeholder comment in #frame-content.
17	     */
18	
19	    * { box-sizing: border-box; margin: 0; padding: 0; }
20	    html, body { height: 100%; overflow: hidden; }
21	
22	    /* ===== THEME VARIABLES ===== */
23	    :root {
24	      --bg-primary: #f5f5f7;
25	      --bg-secondary: #ffffff;
26	      --bg-tertiary: #e5e5e7;
27	      --border: #d1d1d6;
28	      --text-primary: #1d1d1f;
29	      --text-secondary: #86868b;
30	      --text-tertiary: #aeaeb2;
31	      --accent: #0071e3;
32	      --accent-hover: #0077ed;
33	      --success: #34c759;
34	      --warning: #ff9f0a;
35	      --error: #ff3b30;
36	      --selected-bg: #e8f4fd;
37	      --selected-border: #0071e3;
38	    }
39	
40	    @media (prefers-color-scheme: dark) {
41	      :root {
42	        --bg-primary: #1d1d1f;
43	        --bg-secondary: #2d2d2f;
44	        --bg-tertiary: #3d3d3f;
45	        --border: #424245;
46	        --text-primary: #f5f5f7;
47	        --text-secondary: #86868b;
48	        --text-tertiary: #636366;
49	        --accent: #0a84ff;
50	        --accent-hover: #409cff;
51	        --selected-bg: rgba(10, 132, 255, 0.15);
52	        --selected-border: #0a84ff;
53	      }
54	    }
55	
56	    body {
57	      font-family: system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
58	      background: var(--bg-primary);
59	      color: var(--text-primary);
60	      display: flex;
61	      flex-direction: column;
62	      line-height: 1.5;
63	    }
64	
65	    /* ===== FRAME STRUCTURE ===== */
66	    .brand { display: flex; align-items: center; min-width: 0; overflow: hidden; color: var(--text-secondary); line-height: 1; }
67	    .brand a { color: inherit; text-decoration: none; display: flex; align-items: center; gap: 0.5rem; min-width: 0; max-width: 100%; line-height: 1; }
68	    .brand-copy { display: block; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; line-height: 1; transform: translateY(-1px); }
69	    .brand-logo { display: block; height: 1em; width: auto; max-width: 180px; flex-shrink: 0; filter: invert(1); }
70	    @media (prefers-color-scheme: dark) {
71	      .brand-logo { filter: none; }
72	    }
73	    .status { font-size: 0.7rem; color: var(--status-color, var(--success)); display: flex; align-items: center; gap: 0.4rem; justify-self: end; white-space: nowrap; line-height: 1; }
74	    .status::before { content: ''; width: 6px; height: 6px; background: var(--status-color, var(--success)); border-radius: 50%; }
75	
76	    .main { flex: 1; overflow-y: auto; }
77	    #frame-content { padding: 2rem; min-height: 100%; }
78	
79	    .header {
80	      background: var(--bg-secondary);
81	      border-bottom: 1px solid var(--border);
82	      padding: 0.5rem 1.5rem;
83	      flex-shrink: 0;
84	      display: grid;
85	      grid-template-columns: minmax(0, 1fr) auto;
86	      align-items: center;
87	      gap: 1rem;
88	      min-height: 42px;
89	    }
90	    .header .brand { justify-self: start; width: 100%; font-size: 0.75rem; line-height: 1; }
91	    .header .status { grid-column: 2; line-height: 1; }
92	    .header span {
93	      font-size: 0.75rem;
94	      color: var(--text-secondary);
95	    }
96	    .header .selected-text {
97	      color: var(--accent);
98	      font-weight: 500;
99	    }
100	
101	    /* ===== TYPOGRAPHY ===== */
102	    h2 { font-size: 1.5rem; font-weight: 600; margin-bottom: 0.5rem; }
103	    h3 { font-size: 1.1rem; font-weight: 600; margin-bottom: 0.25rem; }
104	    .subtitle { color: var(--text-secondary); margin-bottom: 1.5rem; }
105	    .section { margin-bottom: 2rem; }
106	    .label { font-size: 0.7rem; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 0.5rem; }
107	
108	    /* ===== OPTIONS (for A/B/C choices) ===== */
109	    .options { display: flex; flex-direction: column; gap: 0.75rem; }
110	    .option {
111	      background: var(--bg-secondary);
112	      border: 2px solid var(--border);
113	      border-radius: 12px;
114	      padding: 1rem 1.25rem;
115	      cursor: pointer;
116	      transition: all 0.15s ease;
117	      display: flex;
118	      align-items: flex-start;
119	      gap: 1rem;
120	    }
121	    .option:hover { border-color: var(--accent); }
122	    .option.selected { background: var(--selected-bg); border-color: var(--selected-border); }
123	    .option .letter {
124	      background: var(--bg-tertiary);
125	      color: var(--text-secondary);
126	      width: 1.75rem; height: 1.75rem;
127	      border-radius: 6px;
128	      display: flex; align-items: center; justify-content: center;
129	      font-weight: 600; font-size: 0.85rem; flex-shrink: 0;
130	    }
131	    .option.selected .letter { background: var(--accent); color: white; }
132	    .option .content { flex: 1; }
133	    .option .content h3 { font-size: 0.95rem; margin-bottom: 0.15rem; }
134	    .option .content p { color: var(--text-secondary); font-size: 0.85rem; margin: 0; }
135	
136	    /* ===== CARDS (for showing designs/mockups) ===== */
137	    .cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1rem; }
138	    .card {
