// Throwaway prototype to verify the plan's expected test values. Not product code.
const fmt = (loc, opts) => new Intl.DateTimeFormat(loc, opts);
const part = (f, at, type) => f.formatToParts(at).find((p) => p.type === type)?.value;

const isValidTimeZone = (tz) => { if (!tz) return false; try { fmt('en-US', { timeZone: tz }); return true; } catch { return false; } };
const offsetMinutes = (at, tz) => {
  const v = part(fmt('en-US', { timeZone: tz, timeZoneName: 'longOffset' }), at, 'timeZoneName');
  const m = /GMT([+-])(\d{2}):(\d{2})/.exec(v);
  return m ? (m[1] === '-' ? -1 : 1) * (Number(m[2]) * 60 + Number(m[3])) : 0;
};
const localDate = (at, tz) => {
  const f = fmt('en-US', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' });
  return `${part(f, at, 'year')}-${part(f, at, 'month')}-${part(f, at, 'day')}`;
};
const weekdayOf = (d) => new Date(`${d}T00:00:00Z`).getUTCDay();
const addDays = (d, n) => new Date(Date.parse(`${d}T00:00:00Z`) + n * 86_400_000).toISOString().slice(0, 10);
const zonedTimeToInstant = (date, time, tz) => {
  const [y, mo, d] = date.split('-').map(Number); const [h, mi] = time.split(':').map(Number);
  const wall = Date.UTC(y, mo - 1, d, h, mi);
  const early = offsetMinutes(new Date(wall - 86_400_000), tz), late = offsetMinutes(new Date(wall + 86_400_000), tz);
  const valid = [early, late].map((o) => wall - o * 60_000).filter((t) => offsetMinutes(new Date(t), tz) * 60_000 === wall - t);
  return new Date(valid.length ? Math.min(...valid) : wall - early * 60_000);
};
const formatTime = (at, tz) => fmt('en-US', { timeZone: tz, hour: 'numeric', minute: '2-digit' }).format(at).replace(/ /g, ' ');
const formatDate = (at, tz) => fmt('en-GB', { timeZone: tz, weekday: 'short', day: 'numeric', month: 'short' }).format(at);
const formatDateWithYear = (at, tz) => fmt('en-GB', { timeZone: tz, weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }).format(at);
const formatDayKey = (key) => formatDate(new Date(`${key}T12:00:00Z`), 'UTC');
const LOCALES = ['en-US', 'en-GB', 'en-IE', 'en-IN', 'en-CA', 'en-AU'];
const zoneAbbreviation = (at, tz) => {
  let fallback;
  for (const l of LOCALES) { const n = part(fmt(l, { timeZone: tz, timeZoneName: 'short' }), at, 'timeZoneName'); fallback ??= n; if (!/^(GMT|UTC)[+-]/.test(n)) return n; }
  return fallback;
};
const ALIASES = { 'Asia/Calcutta': 'Kolkata', 'Europe/Kiev': 'Kyiv', 'Asia/Saigon': 'Ho Chi Minh City' };
const cityName = (tz) => ALIASES[tz] ?? tz.split('/').at(-1).replaceAll('_', ' ');
const formatZone = (at, tz) => `${zoneAbbreviation(at, tz)} (${cityName(tz)})`;
const formatWhen = (at, tz) => `${formatDate(at, tz)}, ${formatTime(at, tz)} ${formatZone(at, tz)}`;
const formatSpan = (start, end, tz) => {
  const city = cityName(tz);
  if (offsetMinutes(start, tz) !== offsetMinutes(end, tz)) return `${formatTime(start, tz)} ${zoneAbbreviation(start, tz)}–${formatTime(end, tz)} ${zoneAbbreviation(end, tz)} (${city})`;
  const [s, e] = [formatTime(start, tz), formatTime(end, tz)];
  const [sT, sM] = s.split(' '), [, eM] = e.split(' ');
  return `${sM === eM ? sT : s}–${e} ${zoneAbbreviation(start, tz)} (${city})`;
};
const formatZoneOption = (at, tz) => `${cityName(tz)} (${part(fmt('en-US', { timeZone: tz, timeZoneName: 'shortOffset' }), at, 'timeZoneName')})`;
const canonical = (tz) => fmt('en', { timeZone: tz }).resolvedOptions().timeZone;

const at = (s) => new Date(s);
const out = (label, v) => console.log(label.padEnd(58), JSON.stringify(v));
for (const [tz, iso] of [['America/New_York','2026-01-15T12:00:00Z'],['America/New_York','2026-07-15T12:00:00Z'],['America/Phoenix','2026-01-15T12:00:00Z'],['America/Phoenix','2026-07-15T12:00:00Z'],['Europe/London','2026-01-15T12:00:00Z'],['Europe/London','2026-07-15T12:00:00Z'],['Europe/Dublin','2026-01-15T12:00:00Z'],['Europe/Dublin','2026-07-15T12:00:00Z'],['Asia/Kolkata','2026-01-15T12:00:00Z'],['Asia/Kathmandu','2026-07-15T12:00:00Z']]) out(`offset ${tz} ${iso.slice(0,10)}`, offsetMinutes(at(iso), tz));
for (const [d,t,tz] of [['2026-10-27','20:30','Asia/Kolkata'],['2026-03-08','02:00','America/New_York'],['2026-03-08','02:30','America/New_York'],['2026-03-29','01:30','Europe/London'],['2026-11-01','01:30','America/New_York'],['2026-10-25','01:30','Europe/London'],['2026-11-01','01:00','America/New_York'],['2026-11-01','03:00','America/New_York'],['2026-03-08','05:00','America/New_York'],['2026-03-08','05:30','America/New_York']]) out(`zoned ${d} ${t} ${tz}`, zonedTimeToInstant(d,t,tz).toISOString());
out('localDate 27T01Z LA / Kolkata', [localDate(at('2026-10-27T01:00:00Z'),'America/Los_Angeles'), localDate(at('2026-10-27T01:00:00Z'),'Asia/Kolkata')]);
out('weekdayOf 10-25 / 10-27', [weekdayOf('2026-10-25'), weekdayOf('2026-10-27')]); out('addDays 10-31 +1', addDays('2026-10-31',1));
out('valid', ['Asia/Kolkata','Asia/Calcutta','Europe/Dublin','UTC','IST','Mars/Olympus','','GMT+5:30x','EST'].map((z)=>[z,isValidTimeZone(z)]));
out('formatWhen 27 Oct 16Z London', formatWhen(at('2026-10-27T16:00:00Z'),'Europe/London'));
out('formatWhen 23 Oct 15Z London', formatWhen(at('2026-10-23T15:00:00Z'),'Europe/London'));
out('formatWhen 27 Oct 16Z Kolkata / Calcutta', [formatWhen(at('2026-10-27T16:00:00Z'),'Asia/Kolkata'), formatWhen(at('2026-10-27T16:00:00Z'),'Asia/Calcutta')]);
out('formatWhen 3 Nov 15Z New York', formatWhen(at('2026-11-03T15:00:00Z'),'America/New_York'));
out('abbr Dublin Jul/Jan, Phoenix, Tokyo, NY Jul', [zoneAbbreviation(at('2026-07-15T12:00:00Z'),'Europe/Dublin'), zoneAbbreviation(at('2026-01-15T12:00:00Z'),'Europe/Dublin'), zoneAbbreviation(at('2026-07-15T12:00:00Z'),'America/Phoenix'), zoneAbbreviation(at('2026-01-15T12:00:00Z'),'America/Phoenix'), zoneAbbreviation(at('2026-07-15T12:00:00Z'),'Asia/Tokyo'), zoneAbbreviation(at('2026-07-15T12:00:00Z'),'America/New_York')]);
out('span 16-17Z London', formatSpan(at('2026-10-27T16:00:00Z'), at('2026-10-27T17:00:00Z'),'Europe/London'));
out('span 11-12Z London', formatSpan(at('2026-10-27T11:00:00Z'), at('2026-10-27T12:00:00Z'),'Europe/London'));
out('span 00-01Z 25 Oct London (crosses change)', formatSpan(at('2026-10-25T00:00:00Z'), at('2026-10-25T01:00:00Z'),'Europe/London'));
out('span 16-17Z Kolkata', formatSpan(at('2026-10-27T16:00:00Z'), at('2026-10-27T17:00:00Z'),'Asia/Kolkata'));
out('date with year / day key', [formatDateWithYear(at('2026-10-27T16:00:00Z'),'Europe/London'), formatDayKey('2026-10-25')]);
out('cities', ['America/New_York','America/Indiana/Indianapolis','Asia/Calcutta','Europe/Kiev','UTC'].map(cityName));
out('zone options', [formatZoneOption(at('2026-07-15T12:00:00Z'),'Europe/London'), formatZoneOption(at('2026-01-15T12:00:00Z'),'Europe/London'), formatZoneOption(at('2026-07-15T12:00:00Z'),'Asia/Kolkata')]);
out('canonical Kolkata == Calcutta', canonical('Asia/Kolkata') === canonical('Asia/Calcutta'));
out('supportedValuesOf has Kolkata / Calcutta', [Intl.supportedValuesOf('timeZone').includes('Asia/Kolkata'), Intl.supportedValuesOf('timeZone').includes('Asia/Calcutta')]);
out('formatTime has no U+202F', / /.test(formatTime(at('2026-10-27T16:00:00Z'),'Europe/London')));
out('demo banner sample', `Demo clock: it's ${formatDateWithYear(at('2026-10-20T12:00:00Z'),'Europe/London')}, ${formatTime(at('2026-10-20T12:00:00Z'),'Europe/London')} in London`);

