const fmt = (loc, opts) => new Intl.DateTimeFormat(loc, opts);
const part = (f, at, type) => f.formatToParts(at).find((p) => p.type === type)?.value;

const isValidTimeZone = (tz) => { if (!tz) return false; try { fmt('en-US', { timeZone: tz }); return true; } catch { return false; } };
const offsetMinutes = (at, tz) => {
  const v = part(fmt('en-US', { timeZone: tz, timeZoneName: 'longOffset' }), at, 'timeZoneName');
  const m = /GMT([+-])(\d{2}):(\d{2})/.exec(v);
  return m ? (m[1] === '-' ? -1 : 1) * (Number(m[2]) * 60 + Number(m[3])) : 0;
};
const localDate = (at, tz) => {
  const f = fmt('en-US', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' });
  return `${part(f, at, 'year')}-${part(f, at, 'month')}-${part(f, at, 'day')}`;
};
const weekdayOf = (d) => new Date(`${d}T00:00:00Z`).getUTCDay();
const addDays = (d, n) => new Date(Date.parse(`${d}T00:00:00Z`) + n * 86_400_000).toISOString().slice(0, 10);
const zonedTimeToInstant = (date, time, tz) => {
  const [y, mo, d] = date.split('-').map(Number); const [h, mi] = time.split(':').map(Number);
  const wall = Date.UTC(y, mo - 1, d, h, mi);
  const early = offsetMinutes(new Date(wall - 86_400_000), tz), late = offsetMinutes(new Date(wall + 86_400_000), tz);
  const valid = [early, late].map((o) => wall - o * 60_000).filter((t) => offsetMinutes(new Date(t), tz) * 60_000 === wall - t);
  return new Date(valid.length ? Math.min(...valid) : wall - early * 60_000);
};
const formatTime = (at, tz) => fmt('en-US', { timeZone: tz, hour: 'numeric', minute: '2-digit' }).format(at).replace(/ /g, ' ');
const formatDate = (at, tz) => fmt('en-GB', { timeZone: tz, weekday: 'short', day: 'numeric', month: 'short' }).format(at);
const formatDateWithYear = (at, tz) => fmt('en-GB', { timeZone: tz, weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }).format(at);
const formatDayKey = (key) => formatDate(new Date(`${key}T12:00:00Z`), 'UTC');
const LOCALES = ['en-US', 'en-GB', 'en-IE', 'en-IN', 'en-CA', 'en-AU'];
const zoneAbbreviation = (at, tz) => {
  let fallback;
  for (const l of LOCALES) { const n = part(fmt(l, { timeZone: tz, timeZoneName: 'short' }), at, 'timeZoneName'); fallback ??= n; if (!/^(GMT|UTC)[+-]/.test(n)) return n; }
  return fallback;
};
const ALIASES = { 'Asia/Calcutta': 'Kolkata', 'Europe/Kiev': 'Kyiv', 'Asia/Saigon': 'Ho Chi Minh City' };
const cityName = (tz) => ALIASES[tz] ?? tz.split('/').at(-1).replaceAll('_', ' ');
const formatZone = (at, tz) => `${zoneAbbreviation(at, tz)} (${cityName(tz)})`;
const formatWhen = (at, tz) => `${formatDate(at, tz)}, ${formatTime(at, tz)} ${formatZone(at, tz)}`;
const formatSpan = (start, end, tz) => {
  const city = cityName(tz);
  if (offsetMinutes(start, tz) !== offsetMinutes(end, tz)) return `${formatTime(start, tz)} ${zoneAbbreviation(start, tz)}–${formatTime(end, tz)} ${zoneAbbreviation(end, tz)} (${city})`;
  const [s, e] = [formatTime(start, tz), formatTime(end, tz)];
