  return `${sM === eM ? sT : s}–${e} ${zoneAbbreviation(start, tz)} (${city})`;
};
const formatZoneOption = (at, tz) => `${cityName(tz)} (${part(fmt('en-US', { timeZone: tz, timeZoneName: 'shortOffset' }), at, 'timeZoneName')})`;
const canonical = (tz) => fmt('en', { timeZone: tz }).resolvedOptions().timeZone;

