  ['2026-10-27T16:00:00Z', '2026-10-27T17:00:00Z', 'Asia/Kolkata', '9:30–10:30 PM IST (Kolkata)'],
])('formatSpan(%s, %s, %s)', (start, end, tz, expected) => {
  expect(formatSpan(new Date(start), new Date(end), tz)).toBe(expected);
